class Schema:
    'Class which return list of filled schemas.'
    def __init__(self, schema: SchemaType) -> None:
        """Initialize the Schema class.

        This function initializes an instance of the `Schema` class, setting up a schema that can be either a callable object or an instance of a specific schema type. The constructor accepts a single parameter `schema`, which must be a callable (e.g., a function or method). If provided with a non-callable object, it raises an `UndefinedSchema` exception.

        :param schema: A callable object representing the schema to be used. It must be a function or other callable that defines the structure and constraints for the data being processed.
        :raises UndefinedSchema: Raised if the provided `schema` is not a callable object.

        Example usage:
        --------------
        class MySchema(Schema):
            def __init__(self, schema: SchemaType) -> None:
                super().__init__(schema)

        # Valid call with a callable schema
        my_schema = MySchema(lambda x: x)

        # Invalid call with a non-callable object
        try:
            invalid_schema = MySchema("not_a_callable")
        except UndefinedSchema:
            print("Error: The provided schema is not callable.")
        """
        if callable(schema):
            self.schema = schema
        else:
            raise UndefinedSchema()
